from collections import deque
class Solution:
    def isPossibleToCutPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        def bfs(skip):
            if grid[0][0] == 0:
                return False
            seen = [[False] * n for _ in range(m)]
            par = {}
            dq = deque([(0, 0)])
            seen[0][0] = True
            while dq:
                r, c = dq.popleft()
                if (r, c) == (m - 1, n - 1):
                    return par
                for nr, nc in ((r + 1, c), (r, c + 1)):
                    if nr < m and nc < n and grid[nr][nc] == 1 \
                       and not seen[nr][nc] and (nr, nc) != skip:
                        seen[nr][nc] = True
                        par[(nr, nc)] = (r, c)
                        dq.append((nr, nc))
            return None
        par = bfs(None)
        if par is None:
            return True
        path = []
        cur = (m - 1, n - 1)
        while cur != (0, 0):
            path.append(cur)
            cur = par[cur]
        for cell in path[:-1]:
            if bfs(cell) is None:
                return True
        return False

