class Solution {
public:
    bool isPossibleToCutPath(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        auto bfs = [&](pair<int,int> skip) -> vector<vector<pair<int,int>>> {
            vector<vector<pair<int,int>>> par(m, vector<pair<int,int>>(n, {-1,-1}));
            vector<vector<bool>> seen(m, vector<bool>(n, false));
            if (!grid[0][0]) return {};
            queue<pair<int,int>> q;
            q.push({0,0}); seen[0][0] = true;
            while (!q.empty()) {
                auto [r, c] = q.front(); q.pop();
                if (r == m-1 && c == n-1) return par;
                int dr[] = {1,0}, dc[] = {0,1};
                for (int t = 0; t < 2; t++) {
                    int nr = r + dr[t], nc = c + dc[t];
                    if (nr < m && nc < n && grid[nr][nc] && !seen[nr][nc]
                        && make_pair(nr,nc) != skip) {
                        seen[nr][nc] = true;
                        par[nr][nc] = {r,c};
                        q.push({nr,nc});
                    }
                }
            }
            return {};
        };
        auto par = bfs({-1,-1});
        if (par.empty()) return true;
        vector<pair<int,int>> path;
        pair<int,int> cur = {m-1, n-1};
        while (!(cur.first == 0 && cur.second == 0)) {
            path.push_back(cur);
            cur = par[cur.first][cur.second];
        }
        for (int i = 0; i + 1 < (int)path.size(); i++)
            if (bfs(path[i]).empty()) return true;
        return false;
    }
};

