class Solution {
    public boolean isPossibleToCutPath(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][][] par = new int[m][n][2];
        boolean[][] seen = new boolean[m][n];
        java.util.ArrayDeque<int[]> bfs(java.util.ArrayDeque<int[]> dummy, int sr, int sc) { return null; }
        // helper below
        java.util.function.BiFunction<Integer,Integer,int[][][]> run = null;
        return solve(grid, m, n);
    }
    private boolean solve(int[][] grid, int m, int n) {
        int[][] path = findPath(grid, m, n, -1, -1);
        if (path == null) return true;
        for (int i = 0; i + 1 < path.length; i++)
            if (findPath(grid, m, n, path[i][0], path[i][1]) == null) return true;
        return false;
    }
    private int[][] findPath(int[][] grid, int m, int n, int br, int bc) {
        if (grid[0][0] == 0) return null;
        int[][][] par = new int[m][n][2];
        boolean[][] seen = new boolean[m][n];
        java.util.ArrayDeque<int[]> q = new java.util.ArrayDeque<>();
        q.add(new int[]{0,0}); seen[0][0] = true;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            if (r == m-1 && c == n-1) {
                java.util.List<int[]> list = new java.util.ArrayList<>();
                while (!(r == 0 && c == 0)) { list.add(new int[]{r,c}); int[] p = par[r][c]; r = p[0]; c = p[1]; }
                return list.toArray(new int[0][]);
            }
            int[][] dirs = {{1,0},{0,1}};
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr < m && nc < n && grid[nr][nc] == 1 && !seen[nr][nc] && !(nr == br && nc == bc)) {
                    seen[nr][nc] = true; par[nr][nc] = new int[]{r,c}; q.add(new int[]{nr,nc});
                }
            }
        }
        return null;
    }
}

