var isPossibleToCutPath = function(grid) {
    const m = grid.length, n = grid[0].length;
    const bfs = (br, bc) => {
        if (!grid[0][0]) return null;
        const seen = Array.from({length: m}, () => new Array(n).fill(false));
        const par = Array.from({length: m}, () => new Array(n).fill(null));
        const q = [[0,0]]; seen[0][0] = true;
        while (q.length) {
            const [r, c] = q.shift();
            if (r === m-1 && c === n-1) {
                const path = [];
                let cr = r, cc = c;
                while (!(cr === 0 && cc === 0)) { path.push([cr,cc]); const p = par[cr][cc]; cr = p[0]; cc = p[1]; }
                return path;
            }
            for (const [nr, nc] of [[r+1,c],[r,c+1]])
                if (nr < m && nc < n && grid[nr][nc] === 1 && !seen[nr][nc] && !(nr === br && nc === bc)) {
                    seen[nr][nc] = true; par[nr][nc] = [r,c]; q.push([nr,nc]);
                }
        }
        return null;
    };
    const path = bfs(-1, -1);
    if (!path) return true;
    for (let i = 0; i + 1 < path.length; i++)
        if (!bfs(path[i][0], path[i][1])) return true;
    return false;
};
